import { test } from 'node:test';
import assert from 'node:assert/strict';
import { parseChecklistLine } from './solution.mjs';

test('a checklist line with an item code', () => {
  assert.deepEqual(parseChecklistLine('- [x] `or12` Measuring bench'), { done: true, code: 'or12', text: 'Measuring bench' });
  assert.deepEqual(parseChecklistLine('- [X] `fd3` upper-case box'), { done: true, code: 'fd3', text: 'upper-case box' });
  assert.deepEqual(parseChecklistLine('- [ ] `or12`'), { done: false, code: 'or12', text: '' });
});

test('a checklist line without a code', () => {
  assert.deepEqual(parseChecklistLine('  * [ ]   plain item  '), { done: false, code: null, text: 'plain item' });
  assert.deepEqual(parseChecklistLine('- [ ] `npm test` passes'), { done: false, code: null, text: '`npm test` passes' });
  assert.deepEqual(parseChecklistLine('- [x] `OR12` capitals are not a code'), { done: true, code: null, text: '`OR12` capitals are not a code' });
  assert.deepEqual(parseChecklistLine('- [x] windows line\r'), { done: true, code: null, text: 'windows line' });
});

test('lines that are not checklist lines', () => {
  assert.equal(parseChecklistLine('- [] no box'), null);
  assert.equal(parseChecklistLine('-[x] no space'), null);
  assert.equal(parseChecklistLine('- [x]'), null);
  assert.equal(parseChecklistLine('- [x]    '), null);
  assert.equal(parseChecklistLine('- [y] odd box'), null);
  assert.equal(parseChecklistLine('# heading'), null);
  assert.equal(parseChecklistLine(''), null);
});

test('the shape is strict: the bullet, the space after the box, and what a code looks like', () => {
  assert.equal(parseChecklistLine('+ [x] a'), null);
  assert.equal(parseChecklistLine('- [x]text'), null);
  assert.deepEqual(parseChecklistLine('- [ ] \x60todo\x60 x'), { done: false, code: null, text: '\x60todo\x60 x' });
  assert.deepEqual(parseChecklistLine('- [ ] \x6012ab\x60 x'), { done: false, code: null, text: '\x6012ab\x60 x' });
  assert.deepEqual(parseChecklistLine('\t- [x] \x60ab1\x60 tab'), { done: true, code: 'ab1', text: 'tab' });
  assert.deepEqual(parseChecklistLine('* [x]\ttabbed'), { done: true, code: null, text: 'tabbed' });
});

items.reference:
export function parseChecklistLine(line) {
  const m = /^\s*[-*] +\[([ xX])\]\s+([\s\S]*)$/.exec(String(line));
  if (!m) return null;
  let text = m[2].trim();
  let code = null;
  const c = /^`([a-z]+\d+)`(.*)$/.exec(text);
  if (c) { code = c[1]; text = c[2].trim(); }
  if (!code && !text) return null;
  return { done: m[1] !== ' ', code, text };
}

