import { test } from 'node:test';
import assert from 'node:assert/strict';
import { normalizeWinPath } from './solution.mjs';

test('backslashes, drive letter and trailing slash', () => {
  assert.equal(normalizeWinPath('C:\\dev\\session-map\\'), 'c:/dev/session-map');
  assert.equal(normalizeWinPath('C:\\Dev\\Session-Map'), 'c:/Dev/Session-Map');
  assert.equal(normalizeWinPath('c:/dev/x'), 'c:/dev/x');
  assert.equal(normalizeWinPath('a\\b\\'), 'a/b');
});

test('runs of slashes collapse', () => {
  assert.equal(normalizeWinPath('C:\\\\dev\\\\\\x//y\\'), 'c:/dev/x/y');
  assert.equal(normalizeWinPath('/srv//data///code/'), '/srv/data/code');
});

test('roots keep their slash', () => {
  assert.equal(normalizeWinPath('C:\\'), 'c:/');
  assert.equal(normalizeWinPath('D:/'), 'd:/');
  assert.equal(normalizeWinPath('/'), '/');
});

test('UNC paths keep their two leading slashes', () => {
  assert.equal(normalizeWinPath('\\\\server\\share\\a'), '//server/share/a');
  assert.equal(normalizeWinPath('\\\\server\\\\share\\'), '//server/share');
});

test('dot segments are kept and empty stays empty', () => {
  assert.equal(normalizeWinPath('..\\up\\.\\x'), '../up/./x');
  assert.equal(normalizeWinPath(''), '');
});

test('only a drive letter at the very start is lowercased', () => {
  assert.equal(normalizeWinPath('a/C:/x'), 'a/C:/x');
  assert.equal(normalizeWinPath('x\\D:\\y'), 'x/D:/y');
});

items.reference:
export function normalizeWinPath(p) {
  let s = String(p).replace(/\\/g, '/');
  if (!s) return '';
  const unc = s.startsWith('//');
  s = s.replace(/\/{2,}/g, '/');
  if (unc) s = '/' + s;
  s = s.replace(/^([A-Za-z]):/, (_, d) => d.toLowerCase() + ':');
  if (s.length > 1 && s.endsWith('/') && !/^[a-z]:\/$/.test(s) && s !== '//') s = s.slice(0, -1);
  return s;
}

