test('two decimals and thousands commas', () => {
  assert.equal(formatUSD(0), '$0.00');
  assert.equal(formatUSD(1234.5), '$1,234.50');
  assert.equal(formatUSD(1234567.891), '$1,234,567.89');
  assert.equal(formatUSD(999.999), '$1,000.00');
  assert.equal(formatUSD(12), '$12.00');
});

test('tiny amounts', () => {
  assert.equal(formatUSD(0.004), '<$0.01');
  assert.equal(formatUSD(0.006), '$0.01');
});

test('negative amounts', () => {
  assert.equal(formatUSD(-1.2), '-$1.20');
  assert.equal(formatUSD(-2500), '-$2,500.00');
  assert.equal(formatUSD(-0.001), '$0.00');
});

test('not a finite number', () => {
  assert.equal(formatUSD(NaN), '—');
  assert.equal(formatUSD(Infinity), '—');
  assert.equal(formatUSD('3'), '—');
  assert.equal(formatUSD(null), '—');
  assert.equal(formatUSD(undefined), '—');
});

test('halfway amounts round as the spec says', () => {
  assert.equal(formatUSD(2.675), '$2.68');
  assert.equal(formatUSD(0.125), '$0.13');
  assert.equal(formatUSD(1.005), '$1.00');
  assert.equal(formatUSD(-0.125), '-$0.13');
});

items.reference:
export function formatUSD(n) {
  if (typeof n !== 'number' || !Number.isFinite(n)) return '—';
  if (n > 0 && n < 0.005) return '<$0.01';
  const cents = Math.round(Math.abs(n) * 100);
  if (cents === 0) return '$0.00';
  const whole = String(Math.floor(cents / 100)).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  const s = `$${whole}.${String(cents % 100).padStart(2, '0')}`;
  return n < 0 ? '-' + s : s;
}

