import { test } from 'node:test';
import assert from 'node:assert/strict';
import { shortTitle } from './solution.mjs';

test('short enough: the first non-blank line, whitespace collapsed', () => {
  assert.equal(shortTitle('abcde', 5), 'abcde');
  assert.equal(shortTitle('\n   \n  Fix   the\tmap  \nsecond line', 50), 'Fix the map');
  assert.equal(shortTitle('\r\n  First   line\r\nsecond', 50), 'First line');
});

test('cut at a word boundary with an ellipsis', () => {
  const t = shortTitle('Fix the map so folders grow on the left', 20);
  assert.equal(t, 'Fix the map so…');
  assert.ok(t.length <= 20);
  assert.equal(shortTitle('one two three', 8), 'one two…');
  assert.equal(shortTitle('Hello, world and more', 8), 'Hello…');
});

test('a first word longer than the limit is cut hard', () => {
  assert.equal(shortTitle('Supercalifragilistic word', 10), 'Supercali…');
  assert.equal(shortTitle('abcdef', 2), 'a…');
});

test('nothing to show', () => {
  assert.equal(shortTitle('', 10), '');
  assert.equal(shortTitle('  \n \t\n', 10), '');
});

test('a head left empty by the stripping falls back to a hard cut', () => {
  assert.equal(shortTitle('.. abcdefghijkl', 10), '.. abcdef…');
});

items.reference:
export function shortTitle(text, max) {
  const line = String(text ?? '').split('\n').find((l) => l.trim());
  if (!line) return '';
  const s = line.replace(/\s+/g, ' ').trim();
  if (s.length <= max) return s;
  const sp = s.slice(0, max).lastIndexOf(' ');
  const head = sp > 0 ? s.slice(0, sp).replace(/[\s,;:.\-]+$/, '') : '';
  return (head || s.slice(0, max - 1)) + '…';
}

