import { test } from 'node:test';
import assert from 'node:assert/strict';
import { mergeDailyCost } from './solution.mjs';

test('two projects on overlapping days, sorted by day', () => {
  const out = mergeDailyCost([
    { project: 'map', days: { '2026-10-02': 1.5, '2026-10-01': 2 } },
    { project: 'site', days: { '2026-10-02': 0.25 } },
  ]);
  assert.deepEqual(out, [
    { day: '2026-10-01', total: 2, byProject: { map: 2 } },
    { day: '2026-10-02', total: 1.75, byProject: { map: 1.5, site: 0.25 } },
  ]);
});

test('the same project twice is added up and totals are rounded', () => {
  const out = mergeDailyCost([
    { project: 'map', days: { '2026-10-03': 0.1 } },
    { project: 'map', days: { '2026-10-03': 0.2 } },
    { project: 'app', days: { '2026-10-03': 0.00004 } },
  ]);
  assert.equal(out.length, 1);
  assert.equal(out[0].byProject.map, 0.3);
  assert.equal(out[0].byProject.app, 0);
  assert.equal(out[0].total, 0.3);
});

test('bad values are ignored, a valid zero counts', () => {
  const out = mergeDailyCost([
    { project: 'a', days: { '2026-10-05': NaN, '2026-10-06': -1, '2026-10-07': '2', '2026-10-08': null, '2026-10-09': Infinity } },
    { project: 'b', days: { '2026-10-06': 0, '2026-10-07': 3 } },
  ]);
  assert.deepEqual(out, [
    { day: '2026-10-06', total: 0, byProject: { b: 0 } },
    { day: '2026-10-07', total: 3, byProject: { b: 3 } },
  ]);
});

test('empty input and the input is left untouched', () => {
  assert.deepEqual(mergeDailyCost([]), []);
  const input = [{ project: 'x', days: { '2026-01-02': 1, '2026-01-01': 2 } }, { project: 'x', days: { '2026-01-01': 1 } }];
  const copy = structuredClone(input);
  mergeDailyCost(input);
  assert.deepEqual(input, copy);
});

test('the total is rounded once, after the raw values are added', () => {
  const out = mergeDailyCost([
    { project: 'a', days: { '2026-10-04': 0.00004 } },
    { project: 'b', days: { '2026-10-04': 0.00004 } },
  ]);
  assert.deepEqual(out, [{ day: '2026-10-04', total: 0.0001, byProject: { a: 0, b: 0 } }]);
});

items.reference:
export function mergeDailyCost(projects) {
  const byDay = new Map();
  for (const { project, days } of projects ?? []) {
    for (const [day, v] of Object.entries(days ?? {})) {
      if (typeof v !== 'number' || !Number.isFinite(v) || v < 0) continue;
      if (!byDay.has(day)) byDay.set(day, new Map());
      const m = byDay.get(day);
      m.set(project, (m.get(project) ?? 0) + v);
    }
  }
  const r4 = (x) => Math.round(x * 10000) / 10000;
  return [...byDay.keys()].sort().map((day) => {
    const byProject = {};
    let total = 0;
    for (const [p, v] of byDay.get(day)) {
      Object.defineProperty(byProject, p, { value: r4(v), enumerable: true, writable: true, configurable: true });
      total += v;
    }
    return { day, total: r4(total), byProject };
  });
}

