import { test } from 'node:test';
import assert from 'node:assert/strict';
import { pickModel } from './solution.mjs';

test('the plain table', () => {
  assert.deepEqual(pickModel({ kind: 'search', size: 'medium' }), { model: 'haiku', effort: 'low' });
  assert.deepEqual(pickModel({ kind: 'mechanical', size: 'small' }), { model: 'sonnet', effort: 'medium' });
  assert.deepEqual(pickModel({ kind: 'logic', size: 'medium' }), { model: 'sonnet', effort: 'high' });
  assert.deepEqual(pickModel({ kind: 'logic', size: 'large' }), { model: 'opus', effort: 'high' });
  assert.deepEqual(pickModel({ kind: 'architecture', size: 'small' }), { model: 'opus', effort: 'high' });
});

test('trivial work goes to the cheapest model unless a stronger rule wins', () => {
  assert.deepEqual(pickModel({ kind: 'mechanical', size: 'trivial' }), { model: 'haiku', effort: 'low' });
  assert.deepEqual(pickModel({ kind: 'logic', size: 'trivial', sensitive: false }), { model: 'haiku', effort: 'low' });
  assert.deepEqual(pickModel({ kind: 'search', size: 'trivial', sensitive: true }), { model: 'opus', effort: 'high' });
  assert.deepEqual(pickModel({ kind: 'architecture', size: 'trivial' }), { model: 'opus', effort: 'high' });
});

test('reviews', () => {
  assert.deepEqual(pickModel({ kind: 'review', size: 'trivial' }), { model: 'opus', effort: 'xhigh' });
  assert.deepEqual(pickModel({ kind: 'review', size: 'large', sensitive: true }), { model: 'opus', effort: 'max' });
});

test('bad input throws a TypeError naming the bad value', () => {
  assert.throws(() => pickModel({ kind: 'deploy', size: 'small' }), (e) => e instanceof TypeError && /deploy/.test(e.message));
  assert.throws(() => pickModel({ kind: 'logic', size: 'huge' }), (e) => e instanceof TypeError && /huge/.test(e.message));
  assert.throws(() => pickModel({ kind: 'review', size: 'gigantic', sensitive: true }), (e) => e instanceof TypeError && /gigantic/.test(e.message));
});

test('a new object every time', () => {
  const a = pickModel({ kind: 'search', size: 'small' });
  a.model = 'changed';
  assert.equal(pickModel({ kind: 'search', size: 'small' }).model, 'haiku');
});

test('only logic moves up to opus at size large', () => {
  assert.deepEqual(pickModel({ kind: 'mechanical', size: 'large' }), { model: 'sonnet', effort: 'medium' });
  assert.deepEqual(pickModel({ kind: 'search', size: 'large' }), { model: 'haiku', effort: 'low' });
  assert.deepEqual(pickModel({ kind: 'logic', size: 'small' }), { model: 'sonnet', effort: 'high' });
});

items.reference:
const KINDS = ['search', 'mechanical', 'logic', 'architecture', 'review'];
const SIZES = ['trivial', 'small', 'medium', 'large'];

export function pickModel({ kind, size, sensitive = false } = {}) {
  if (!KINDS.includes(kind)) throw new TypeError(`unknown kind: ${kind}`);
  if (!SIZES.includes(size)) throw new TypeError(`unknown size: ${size}`);
  if (kind === 'review') return { model: 'opus', effort: size === 'large' ? 'max' : 'xhigh' };
  if (kind === 'architecture' || sensitive === true) return { model: 'opus', effort: 'high' };
  if (size === 'trivial') return { model: 'haiku', effort: 'low' };
  if (kind === 'search') return { model: 'haiku', effort: 'low' };
  if (kind === 'mechanical') return { model: 'sonnet', effort: 'medium' };
  return size === 'large' ? { model: 'opus', effort: 'high' } : { model: 'sonnet', effort: 'high' };
}

