import { test } from 'node:test';
import assert from 'node:assert/strict';
import { debounceAlerts } from './solution.mjs';

const keysAt = (evs) => evs.map((e) => `${e.key}@${e.at}`);

test('repeats inside the window are dropped, other keys are independent', () => {
  const evs = [{ key: 'a', at: 0 }, { key: 'b', at: 100 }, { key: 'a', at: 500 }, { key: 'b', at: 1200 }];
  assert.deepEqual(keysAt(debounceAlerts(evs, 1000)), ['a@0', 'b@100', 'b@1200']);
});

test('exactly one window apart is delivered', () => {
  assert.deepEqual(keysAt(debounceAlerts([{ key: 'a', at: 0 }, { key: 'a', at: 1000 }], 1000)), ['a@0', 'a@1000']);
});

test('suppressed events do not restart the window', () => {
  const evs = [{ key: 'a', at: 0 }, { key: 'a', at: 600 }, { key: 'a', at: 1100 }, { key: 'a', at: 1500 }, { key: 'a', at: 2100 }];
  assert.deepEqual(keysAt(debounceAlerts(evs, 1000)), ['a@0', 'a@1100', 'a@2100']);
});

test('unsorted input is processed by time, ties keep input order', () => {
  const evs = [{ key: 'a', at: 900 }, { key: 'x', at: 5, n: 1 }, { key: 'a', at: 0 }, { key: 'x', at: 5, n: 2 }, { key: 'y', at: 5 }];
  const out = debounceAlerts(evs, 1000);
  assert.deepEqual(keysAt(out), ['a@0', 'x@5', 'y@5']);
  assert.equal(out[1].n, 1);
});

test('same objects back, input untouched, zero window', () => {
  const evs = [{ key: 'a', at: 2 }, { key: 'a', at: 1 }];
  const out = debounceAlerts(evs, 0);
  assert.equal(out.length, 2);
  assert.equal(out[0], evs[1]);
  assert.deepEqual(evs, [{ key: 'a', at: 2 }, { key: 'a', at: 1 }]);
  assert.deepEqual(debounceAlerts([], 1000), []);
});

items.reference:
export function debounceAlerts(events, windowMs) {
  const order = events.map((e, i) => [e, i]).sort((x, y) => x[0].at - y[0].at || x[1] - y[1]);
  const last = new Map();
  const out = [];
  for (const [e] of order) {
    if (last.has(e.key) && e.at - last.get(e.key) < windowMs) continue;
    last.set(e.key, e.at);
    out.push(e);
  }
  return out;
}

