import { test } from 'node:test';
import assert from 'node:assert/strict';
import { rankConversations } from './solution.mjs';

const NOW = Date.parse('2026-10-10T12:00:00Z');
const MIN = 60 * 1000;

test('groups come in order, most recent first inside each', () => {
  const convs = [
    { id: 'd1', state: 'done', lastActivity: NOW - 1 * MIN },
    { id: 'i1', state: 'idle', lastActivity: NOW - 5 * MIN },
    { id: 'w1', state: 'waiting', lastActivity: NOW - 50 * MIN },
    { id: 'k1', state: 'working', lastActivity: NOW - 2 * MIN },
    { id: 'w2', state: 'waiting', lastActivity: NOW - 1 * MIN },
    { id: 'z1', state: 'archived', lastActivity: NOW },
  ];
  assert.deepEqual(rankConversations(convs, NOW), ['w2', 'w1', 'k1', 'i1', 'd1', 'z1']);
});

test('a working conversation quiet for more than 30 minutes counts as idle', () => {
  const convs = [
    { id: 'old', state: 'working', lastActivity: NOW - 31 * MIN },
    { id: 'edge', state: 'working', lastActivity: NOW - 30 * MIN },
    { id: 'idle', state: 'idle', lastActivity: NOW - 40 * MIN },
  ];
  assert.deepEqual(rankConversations(convs, NOW), ['edge', 'old', 'idle']);
});

test('date strings and numbers mix, equal times go by id', () => {
  const convs = [
    { id: 'b', state: 'idle', lastActivity: '2026-10-10T11:00:00Z' },
    { id: 'a', state: 'idle', lastActivity: NOW - 60 * MIN },
    { id: 'c', state: 'idle', lastActivity: '2026-10-10T11:30:00Z' },
  ];
  assert.deepEqual(rankConversations(convs, NOW), ['c', 'a', 'b']);
});

test('unreadable times are the oldest', () => {
  const convs = [
    { id: 'n', state: 'done', lastActivity: 'not a date' },
    { id: 'm', state: 'done' },
    { id: 'o', state: 'done', lastActivity: NOW - 999 * MIN },
    { id: 'p', state: 'working', lastActivity: NaN },
  ];
  assert.deepEqual(rankConversations(convs, NOW), ['p', 'o', 'm', 'n']);
});

test('the input is left untouched', () => {
  const convs = [{ id: 'x', state: 'done', lastActivity: 1 }, { id: 'y', state: 'waiting', lastActivity: 2 }];
  const copy = structuredClone(convs);
  assert.deepEqual(rankConversations(convs, NOW), ['y', 'x']);
  assert.deepEqual(convs, copy);
  assert.deepEqual(rankConversations([], NOW), []);
});

test('equal times go by plain string order of the ids', () => {
  const at = NOW - 3 * MIN;
  assert.deepEqual(rankConversations([{ id: 'a', state: 'idle', lastActivity: at }, { id: 'B', state: 'idle', lastActivity: at }], NOW), ['B', 'a']);
  assert.deepEqual(rankConversations([{ id: 'a9', state: 'done', lastActivity: at }, { id: 'a10', state: 'done', lastActivity: at }], NOW), ['a10', 'a9']);
});

