const GROUP = { waiting: 0, working: 1, idle: 2, done: 3 };
const STALE_MS = 30 * 60 * 1000;

function timeOf(v) {
  if (typeof v === 'number') return Number.isFinite(v) ? v : -Infinity;
  if (typeof v === 'string') { const t = Date.parse(v); return Number.isNaN(t) ? -Infinity : t; }
  return -Infinity;
}

export function rankConversations(convs, now) {
  const rows = convs.map((c) => {
    const t = timeOf(c.lastActivity);
    let g = Object.hasOwn(GROUP, c.state) ? GROUP[c.state] : 4;
    if (c.state === 'working' && now - t > STALE_MS) g = GROUP.idle;
    return { id: c.id, g, t };
  });
  rows.sort((a, b) => a.g - b.g || (a.t === b.t ? (a.id < b.id ? -1 : a.id > b.id ? 1 : 0) : b.t - a.t));
  return rows.map((r) => r.id);
}

