export function parseArgs(argv, spec) {
  const out = { _: [] };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === '--') { out._.push(...argv.slice(i + 1)); break; }
    if (!a.startsWith('--')) { out._.push(a); continue; }
    const eq = a.indexOf('=');
    const name = eq === -1 ? a.slice(2) : a.slice(2, eq);
    const type = Object.hasOwn(spec, name) ? spec[name] : undefined;
    if (!type) throw new Error(`unknown option --${name}`);
    let value = eq === -1 ? undefined : a.slice(eq + 1);
    if (type === 'boolean') {
      if (value === undefined) out[name] = true;
      else if (value === 'true' || value === 'false') out[name] = value === 'true';
      else throw new Error(`--${name} takes true or false, not ${value}`);
      continue;
    }
    if (value === undefined) {
      const next = argv[i + 1];
      if (next === undefined || next.startsWith('--')) throw new Error(`--${name} needs a value`);
      value = next;
      i++;
    }
    if (value === '') throw new Error(`--${name} needs a value`);
    if (type === 'number') {
      const n = Number(value);
      if (!Number.isFinite(n)) throw new Error(`--${name} needs a number, not ${value}`);
      out[name] = n;
    } else if (type === 'list') {
      out[name] = value.split(',').map((s) => s.trim()).filter(Boolean);
    } else {
      out[name] = value;
    }
  }
  return out;
}

