export function budgetState(spentUSD, limitUSD) {
  if (typeof limitUSD !== 'number' || !Number.isFinite(limitUSD) || limitUSD <= 0) return { pct: 0, level: 'none' };
  const spent = typeof spentUSD === 'number' && Number.isFinite(spentUSD) && spentUSD > 0 ? spentUSD : 0;
  const share = spent / limitUSD;
  return { pct: Math.floor(share * 100), level: share >= 1 ? 'over' : share >= 0.8 ? 'warn' : 'ok' };
}

