export function splitAtHeadings(md, maxChars) {
  const lines = String(md).replace(/\r\n/g, '\n').split('\n');
  const sections = [];
  let cur = [];
  let fence = false;
  for (const line of lines) {
    if (line.trimStart().startsWith('```')) fence = !fence;
    else if (!fence && /^#{1,6} /.test(line)) { sections.push(cur); cur = []; }
    cur.push(line);
  }
  sections.push(cur);
  const out = [];
  for (const sec of sections) {
    const text = sec.join('\n').replace(/^\n+/, '').trimEnd();
    if (!text) continue;
    if (text.length <= maxChars) { out.push(text); continue; }
    let chunk = '';
    for (const para of text.split(/\n{2,}/)) {
      if (!chunk) chunk = para;
      else if (chunk.length + 2 + para.length <= maxChars) chunk += '\n\n' + para;
      else { out.push(chunk); chunk = para; }
    }
    if (chunk) out.push(chunk);
  }
  return out;
}

items.spec:
Read the simple YAML-like frontmatter at the top of a markdown file (skills and agents use it).

Split the text on '\n'; when comparing or reading a line, ignore one '\r' at its end. The text has frontmatter only when its first line is exactly '---' and some later line is exactly '---' (the first such later line closes it). Without frontmatter, return { data: {}, body: text } with text unchanged.

Inside the frontmatter, skip blank lines and lines starting with '#'. Every other line is read with the pattern: a key made of [A-Za-z0-9_-]+, then ':', then either the end of the line or a space followed by the raw value. Lines that do not fit the pattern (for example 'url:http://x' with no space after the colon) are ignored. A later key overrides an earlier one.

Values (trim the raw value first):
- '' (nothing), 'null' or '~' give null; 'true' and 'false' give booleans;
- text matching /^-?\d+(\.\d+)?$/ gives a Number;
- text of at least 2 characters wrapped in a matching pair of double quotes or single quotes gives the text inside, exactly as is (no escapes, no further conversion: "'42'" stays the string '42');
- text starting with '[' and ending with ']' gives an array: split what is inside the brackets on every comma, trim each piece, drop empty pieces, and convert each piece by the rules above (no nested lists, '[]' gives []);
- anything else is the trimmed text as a string.

body is the text after the closing '---' line: the lines after it joined back with '\n' (the line break right after the closing line is not part of body, and the other lines keep any '\r' they had).

