items.reference:
function scalar(raw) {
  const v = raw.trim();
  if (v === '' || v === 'null' || v === '~') return null;
  if (v === 'true') return true;
  if (v === 'false') return false;
  if (/^-?\d+(\.\d+)?$/.test(v)) return Number(v);
  if (v.length >= 2 && (v[0] === '"' || v[0] === "'") && v.at(-1) === v[0]) return v.slice(1, -1);
  return v;
}

export function parseFrontmatter(text) {
  const s = String(text);
  const lines = s.split('\n');
  const clean = (l) => (l.endsWith('\r') ? l.slice(0, -1) : l);
  if (clean(lines[0]) !== '---') return { data: {}, body: s };
  const end = lines.findIndex((l, i) => i > 0 && clean(l) === '---');
  if (end === -1) return { data: {}, body: s };
  const data = {};
  for (const raw of lines.slice(1, end)) {
    const line = clean(raw);
    if (!line.trim() || line.startsWith('#')) continue;
    const m = /^([A-Za-z0-9_-]+):(?: ([\s\S]*))?$/.exec(line);
    if (!m) continue;
    const v = (m[2] ?? '').trim();
    const value = v.startsWith('[') && v.endsWith(']')
      ? v.slice(1, -1).split(',').map((x) => x.trim()).filter(Boolean).map(scalar)
      : scalar(v);
    Object.defineProperty(data, m[1], { value, enumerable: true, writable: true, configurable: true });
  }
  return { data, body: lines.slice(end + 1).join('\n') };
}

items.spec:
Compute a line diff between an old text a and a new text b, as shown in the changes view.

Split each text on '\n'; an empty text is zero lines (not one empty line), and a final '\n' gives a last empty line ('x\n' is the two lines 'x' and ''). Return an array of { op, line } where op is ' ' (line kept), '-' (line only in a) or '+' (line only in b), such that:
- the ' ' and '-' entries, in order, give exactly the lines of a;
- the ' ' and '+' entries, in order, give exactly the lines of b;
- the number of ' ' entries is as large as possible (the kept lines are a longest common subsequence of the two line lists).

When several answers meet these rules, any of them is accepted. Texts of up to 2000 lines each must be handled in well under a second.

items.tests:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { diffLines } from './solution.mjs';

const lines = (s) => (s === '' ? [] : s.split('\n'));

function check(a, b, kept) {
  const d = diffLines(a, b);
  assert.ok(Array.isArray(d));
  assert.ok(d.every((e) => [' ', '-', '+'].includes(e.op) && typeof e.line === 'string'), 'every entry is {op, line}');
  assert.deepEqual(d.filter((e) => e.op !== '+').map((e) => e.line), lines(a), 'the old text comes back');
  assert.deepEqual(d.filter((e) => e.op !== '-').map((e) => e.line), lines(b), 'the new text comes back');
  assert.equal(d.filter((e) => e.op === ' ').length, kept, 'as many kept lines as possible');
}

test('same, empty and one-sided texts', () => {
  check('a\nb\nc', 'a\nb\nc', 3);
  assert.deepEqual(diffLines('', ''), []);
  check('', 'x\ny', 0);
  check('x\ny', '', 0);
});

test('a changed line, an insertion and a removal', () => {
  check('a\nb\nc\nd', 'a\nB\nc\nd', 3);
  check('a\nb\nc', 'a\nnew\nb\nc', 3);
  check('a\nb\nc\nd', 'a\nd', 2);
});

test('moved and repeated lines keep the longest common part', () => {
  check('a\na\nb', 'a\nb\na', 2);
  check('x\na\nb\nc\ny', 'a\nb\nc\nx\ny', 4);
  check('1\n2\n3\n4\n5\n6', '6\n1\n2\n4\n3\n5', 4);
});

test('a final line break is a last empty line', () => {
  check('x\n', 'x', 1);
  check('x', 'x\n', 1);
});

test('2000 lines are fast', () => {
  const a = Array.from({ length: 2000 }, (_, i) => `l${i}`);
  const b = a.map((l, i) => (i % 100 === 50 ? `x${i}` : l));
  b.splice(1000, 0, 'inserted');
  const t0 = performance.now();
  check(a.join('\n'), b.join('\n'), 1980);
  assert.ok(performance.now() - t0 < 1000, 'took too long');
  const c = a.map((l) => 'other ' + l);
  const t1 = performance.now();
  check(a.join('\n'), c.join('\n'), 0);
  assert.ok(performance.now() - t1 < 1000, 'took too long on two texts with nothing in common');
});

items.reference:
export function diffLines(a, b) {
  const A = a === '' ? [] : a.split('\n');
  const B = b === '' ? [] : b.split('\n');
  let pre = 0;
  while (pre < A.length && pre < B.length && A[pre] === B[pre]) pre++;
  let suf = 0;
  while (suf < A.length - pre && suf < B.length - pre && A[A.length - 1 - suf] === B[B.length - 1 - suf]) suf++;
  const a2 = A.slice(pre, A.length - suf);
  const b2 = B.slice(pre, B.length - suf);
  const n = a2.length;
  const m = b2.length;
  const dp = Array.from({ length: n + 1 }, () => new Uint32Array(m + 1));
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      dp[i][j] = a2[i] === b2[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1]);
    }
  }
  const out = A.slice(0, pre).map((line) => ({ op: ' ', line }));
  let i = 0;
  let j = 0;
  while (i < n && j < m) {
    if (a2[i] === b2[j]) { out.push({ op: ' ', line: a2[i] }); i++; j++; }
    else if (dp[i + 1][j] >= dp[i][j + 1]) out.push({ op: '-', line: a2[i++] });
    else out.push({ op: '+', line: b2[j++] });
  }
  while (i < n) out.push({ op: '-', line: a2[i++] });
  while (j < m) out.push({ op: '+', line: b2[j++] });
  for (const line of A.slice(A.length - suf)) out.push({ op: ' ', line });
  return out;
}

