const escapeText = (s) => s.replace(/[.*+?^${}()|[\]\\\/]/g, '\\$&');

export function globToRegExp(glob) {
  const g = String(glob);
  let re = '';
  let i = 0;
  while (i < g.length) {
    const c = g[i];
    if (c === '*' && g[i + 1] === '*') {
      const startsSegment = i === 0 || g[i - 1] === '/';
      const endsSegment = i + 2 === g.length || g[i + 2] === '/';
      if (startsSegment && endsSegment) {
        if (g[i + 2] === '/') { re += '(?:[^/]*/)*'; i += 3; continue; }
        re += i === 0 ? '[\\s\\S]*' : '[\\s\\S]+';
        i += 2;
        continue;
      }
      re += '[^/]*';
      i += 2;
      continue;
    }
    if (c === '*') { re += '[^/]*'; i++; continue; }
    if (c === '?') { re += '[^/]'; i++; continue; }
    if (c === '{') {
      const close = g.indexOf('}', i + 1);
      if (close !== -1) {
        re += '(?:' + g.slice(i + 1, close).split(',').map(escapeText).join('|') + ')';
        i = close + 1;
        continue;
      }
    }
    re += escapeText(c);
    i++;
  }
  return new RegExp('^' + re + '$');
}

