export function extractJSON(text) {
  if (typeof text !== 'string') return { ok: false, error: 'the answer is not text' };
  const start = text.indexOf('{');
  if (start === -1) return { ok: false, error: 'no object in the answer' };
  let depth = 0;
  let inString = false;
  for (let i = start; i < text.length; i++) {
    const c = text[i];
    if (inString) {
      if (c === '\\') i++;
      else if (c === '"') inString = false;
      continue;
    }
    if (c === '"') inString = true;
    else if (c === '{') depth++;
    else if (c === '}' && --depth === 0) {
      try {
        return { ok: true, value: JSON.parse(text.slice(start, i + 1)) };
      } catch (e) {
        return { ok: false, error: String(e?.message || 'the object does not parse') };
      }
    }
  }
  return { ok: false, error: 'the object is not closed' };
}

