test('a pre-release is older than its release', () => {
  assert.equal(semverCompare('1.0.0-rc.1', '1.0.0'), -1);
  assert.equal(semverCompare('1.0.0', '1.0.0-rc.1'), 1);
  assert.equal(semverCompare('1.0.1-alpha', '1.0.0'), 1);
});

test('pre-release identifiers, one by one', () => {
  assert.equal(semverCompare('1.0.0-rc.2', '1.0.0-rc.10'), -1);
  assert.equal(semverCompare('1.0.0-rc.10', '1.0.0-rc.2'), 1);
  assert.equal(semverCompare('1.0.0-rc.1', '1.0.0-rc.1'), 0);
  assert.equal(semverCompare('1.0.0-1', '1.0.0-alpha'), -1);
  assert.equal(semverCompare('1.0.0-alpha', '1.0.0-beta'), -1);
  assert.equal(semverCompare('1.0.0-alpha', '1.0.0-alpha.1'), -1);
  assert.equal(semverCompare('1.0.0-alpha.beta', '1.0.0-alpha.1'), 1);
  assert.equal(semverCompare('1.0.0-A', '1.0.0-a'), -1);
  assert.equal(semverCompare('1.0.0-alpha-1', '1.0.0-alpha-2'), -1);
});

test('the order of the semver.org example chain, however it is shuffled', () => {
  const chain = ['1.0.0-alpha', '1.0.0-alpha.1', '1.0.0-alpha.beta', '1.0.0-beta', '1.0.0-beta.2', '1.0.0-beta.11', '1.0.0-rc.1', '1.0.0'];
  const shuffled = [chain[5], chain[0], chain[7], chain[2], chain[6], chain[1], chain[4], chain[3]];
  assert.deepEqual(shuffled.sort(semverCompare), chain);
});

test('build metadata never matters', () => {
  assert.equal(semverCompare('1.0.0+a', '1.0.0+b'), 0);
  assert.equal(semverCompare('1.0.0-rc.1+x', '1.0.0-rc.1'), 0);
