});

test('of the items ready together, the first in the input goes first, at every step', () => {
  assert.deepEqual(planOrder([{ id: 'a', after: ['b'] }, { id: 'b' }, { id: 'c' }]), { ok: true, order: ['b', 'a', 'c'] });
