  assert.deepEqual(planOrder(undefined), { ok: true, order: [] });
  assert.deepEqual(planOrder('abc'), { ok: true, order: [] });
});

test('a cycle, directly or through others, names everything it holds back', () => {
  assert.deepEqual(planOrder([{ id: 'a', after: ['b'] }, { id: 'b', after: ['a'] }, { id: 'c' }, { id: 'd', after: ['a'] }]), { ok: false, stuck: ['a', 'b', 'd'] });
  assert.deepEqual(planOrder([{ id: 'x', after: ['x'] }, { id: 'y' }]), { ok: false, stuck: ['x'] });
  assert.deepEqual(planOrder([{ id: 'e', after: ['d'] }, { id: 'd', after: ['e'] }]), { ok: false, stuck: ['e', 'd'] });
});

