export function planOrder(items) {
  if (!Array.isArray(items)) return { ok: true, order: [] };
  const known = new Set();
  const list = [];
  for (const it of items) {
    if (it && typeof it === 'object' && typeof it.id === 'string' && !known.has(it.id)) {
      known.add(it.id);
      list.push(it);
    }
  }
  const waits = new Map(list.map((it) => [it.id, (Array.isArray(it.after) ? it.after : []).filter((x) => known.has(x))]));
  const placed = new Set();
  const order = [];
  while (order.length < list.length) {
    const next = list.find((it) => !placed.has(it.id) && waits.get(it.id).every((x) => placed.has(x)));
    if (!next) break;
    placed.add(next.id);
    order.push(next.id);
  }
  if (order.length === list.length) return { ok: true, order };
  return { ok: false, stuck: list.filter((it) => !placed.has(it.id)).map((it) => it.id) };
}

