  assert.equal(wrapText('one\n\ntwo three', 7), 'one\n\ntwo\nthree');
  assert.equal(wrapText('a\nb', 10), 'a\nb');
  assert.equal(wrapText('', 5), '');
  assert.equal(wrapText('\n', 5), '\n');
});

test('a word longer than the width is cut and starts on its own line', () => {
  assert.equal(wrapText('abcdefghij', 4), 'abcd\nefgh\nij');
  assert.equal(wrapText('abcdefgh', 4), 'abcd\nefgh');
  assert.equal(wrapText('x abcdefghij y', 4), 'x\nabcd\nefgh\nij y');
  assert.equal(wrapText('ab cdefghijkl', 5), 'ab\ncdefg\nhijkl');
});

