  assert.throws(() => wrapText(42, 10), TypeError);
  assert.throws(() => wrapText('a', 0), RangeError);
  assert.throws(() => wrapText('a', 2.5), RangeError);
  assert.throws(() => wrapText('a', '5'), RangeError);
});

